def maxScore(nums, maxVal):
    n = len(nums)
    M = max(maxVal, max(nums))

    # Smallest prime factor sieve
    spf = list(range(M + 1))
    i = 2
    while i * i <= M:
        if spf[i] == i:
            for j in range(i * i, M + 1, i):
                if spf[j] == j:
                    spf[j] = i
        i += 1

    # Mobius function (0 when v has a squared prime factor)
    mu = [0] * (M + 1)
    mu[1] = 1
    for v in range(2, M + 1):
        p = spf[v]
        q = v // p
        if q % p != 0:
            mu[v] = -mu[q]

    # freq[v] = how many elements equal v
    freq = [0] * (M + 1)
    for x in nums:
        freq[x] += 1

    # div_cnt[d] = how many elements are divisible by d (only for squarefree d)
    div_cnt = [0] * (M + 1)
    for d in range(1, M + 1):
        if mu[d] != 0:
            total = 0
            for multiple in range(d, M + 1, d):
                total += freq[multiple]
            div_cnt[d] = total

    # For each v, list its distinct primes
    def distinct_primes(v):
        primes = []
        while v > 1:
            p = spf[v]
            primes.append(p)
            while v % p == 0:
                v //= p
        return primes

    # coprime_count(v) = number of elements with gcd(element, v) == 1,
    # by inclusion-exclusion over the squarefree divisors of v.
    def coprime_count(v):
        divisors = [1]
        signs = [1]
        for p in distinct_primes(v):
            for idx in range(len(divisors)):
                divisors.append(divisors[idx] * p)
                signs.append(-signs[idx])
        total = 0
        for d, sg in zip(divisors, signs):
            total += sg * div_cnt[d]
        return total

    best = float('-inf')

    # Case A: keep one existing element unchanged, change every non-coprime other
    for v in set(nums):
        coprime_all = coprime_count(v)
        if v == 1:
            bad = 0          # 1 is coprime with everything
        else:
            bad = n - 1 - coprime_all   # v itself is never coprime with v
        best = max(best, v - bad)

    # Case B: change the chosen element itself to some v <= maxVal (cost 1)
    for v in range(1, maxVal + 1):
        bad_all = n - coprime_count(v)
        # If some element is not coprime with v, choose that one to overwrite
        best = max(best, v - max(1, bad_all))

    return best
